arguments.command:
python3 -c "
import json
with open('/app/resources/treasury_bulletin_1982_08.json', 'r') as f:
    data = json.load(f)
# Print keys
def print_keys(d, prefix=''):
    for k, v in d.items():
        print(f'{prefix}{k}')
        if isinstance(v, dict):
            print_keys(v, prefix + '  ')
        elif isinstance(v, list):
            print(f'{prefix}  (list of {len(v)} items)')
            if len(v) > 0:
                if isinstance(v[0], dict):
                    print_keys(v[0], prefix + '    ')
print_keys(data)
"
